uint32_t cvkParseJsonValue(cvkJsonReader* pReader)
{
    uint32_t      index;
    uint32_t      previous;
    uint32_t      child;
    const char*   p;
    cvkJsonValue* value;

    while ((pReader->pCursor < pReader->pEnd) && ((' ' == *pReader->pCursor) || ('\t' == *pReader->pCursor) || ('\n' == *pReader->pCursor) || ('\r' == *pReader->pCursor)))
    {
        ++pReader->pCursor;
    }
    CVK_ASSERT(pReader->pCursor < pReader->pEnd);
    CVK_ASSERT(pReader->valueCount < pReader->valueCapacity);

    index              = pReader->valueCount++;
    value              = &pReader->pValues[index];
    value->kind        = CVK_JSON_NULL;
    value->pText       = NULL;
    value->textLength  = 0;
    value->pKey        = NULL;
    value->keyLength   = 0;
    value->childCount  = 0;
    value->firstChild  = CVK_JSON_NONE;
    value->nextSibling = CVK_JSON_NONE;
    p                  = pReader->pCursor;
    if ('{' == *p || '[' == *p)
    {
        const char close = ('{' == *p) ? '}' : ']';

        value->kind      = ('{' == *p) ? CVK_JSON_OBJECT : CVK_JSON_ARRAY;
        pReader->pCursor = p + 1;
        previous         = CVK_JSON_NONE;
        for (;;)
        {
            while ((pReader->pCursor < pReader->pEnd) && ((' ' == *pReader->pCursor) || ('\t' == *pReader->pCursor) || ('\n' == *pReader->pCursor) || ('\r' == *pReader->pCursor)))
            {
                ++pReader->pCursor;
            }
            CVK_ASSERT(pReader->pCursor < pReader->pEnd);

            if (close == *pReader->pCursor)
            {
                ++pReader->pCursor;
                break;
            }
            if (CVK_JSON_OBJECT == value->kind)
            {
                const char* key;
                const char* key_end;

                CVK_ASSERT('"' == *pReader->pCursor);

                key     = pReader->pCursor + 1;
                key_end = key;
                while ((key_end < pReader->pEnd) && ('"' != *key_end))
                {
                    key_end += ('\\' == *key_end) ? 2 : 1;
                }
                CVK_ASSERT(key_end < pReader->pEnd);

                pReader->pCursor = key_end + 1;
                while ((pReader->pCursor < pReader->pEnd) && ((' ' == *pReader->pCursor) || ('\t' == *pReader->pCursor) || ('\n' == *pReader->pCursor) || ('\r' == *pReader->pCursor)))
                {
                    ++pReader->pCursor;
                }
                CVK_ASSERT((pReader->pCursor < pReader->pEnd) && (':' == *pReader->pCursor));

                ++pReader->pCursor;
                child = cvkParseJsonValue(pReader);

                pReader->pValues[child].pKey      = key;
                pReader->pValues[child].keyLength = (uint32_t)(key_end - key);
            }
            else
            {
                child = cvkParseJsonValue(pReader);
            }
            value = &pReader->pValues[index]; /* the value array is stable, the pointer is re-read for clarity */
            if (CVK_JSON_NONE == previous)
            {
                value->firstChild = child;
            }
            else
            {
                pReader->pValues[previous].nextSibling = child;
            }
            previous = child;
            ++value->childCount;
            while ((pReader->pCursor < pReader->pEnd) && ((' ' == *pReader->pCursor) || ('\t' == *pReader->pCursor) || ('\n' == *pReader->pCursor) || ('\r' == *pReader->pCursor)))
            {
                ++pReader->pCursor;
            }
            CVK_ASSERT(pReader->pCursor < pReader->pEnd);

            if (',' == *pReader->pCursor)
            {
                ++pReader->pCursor;
                continue;
            }
            CVK_ASSERT(close == *pReader->pCursor);

            ++pReader->pCursor;
            break;
        }

        return index;
    }
    if ('"' == *p)
    {
        const char* end = p + 1;

        while ((end < pReader->pEnd) && ('"' != *end))
        {
            end += ('\\' == *end) ? 2 : 1;
        }
        CVK_ASSERT(end < pReader->pEnd);

        value->kind       = CVK_JSON_STRING;
        value->pText      = p + 1;
        value->textLength = (uint32_t)(end - (p + 1));
        pReader->pCursor  = end + 1;

        return index;
    }
    if ('t' == *p || 'f' == *p || 'n' == *p)
    {
        const char* literal = ('t' == *p) ? "true" : (('f' == *p) ? "false" : "null");

        const size_t length = strlen(literal);

        CVK_ASSERT(((size_t)(pReader->pEnd - p) >= length) && (0 == memcmp(p, literal, length)));

        value->kind      = ('t' == *p) ? CVK_JSON_TRUE : (('f' == *p) ? CVK_JSON_FALSE : CVK_JSON_NULL);
        pReader->pCursor = p + length;

        return index;
    }
    {
        const char* end = p;

        while ((end < pReader->pEnd) && (('-' == *end) || ('+' == *end) || ('.' == *end) || ('e' == *end) || ('E' == *end) || (('0' <= *end) && ('9' >= *end))))
        {
            ++end;
        }
        CVK_ASSERT(end > p);

        value->kind       = CVK_JSON_NUMBER;
        value->pText      = p;
        value->textLength = (uint32_t)(end - p);
        pReader->pCursor  = end;

        return index;
    }
}
uint32_t cvkParseJsonDocument(const char* pText, size_t length, cvkJsonValue* pValues, uint32_t valueCapacity)
{
    cvkJsonReader reader;
    uint32_t      root;

    reader.pCursor       = pText;
    reader.pEnd          = pText + length;
    reader.pValues       = pValues;
    reader.valueCapacity = valueCapacity;
    reader.valueCount    = 0;

    root = cvkParseJsonValue(&reader);
    CVK_ASSERT(0 == root);

    while ((reader.pCursor < reader.pEnd) && ((' ' == *reader.pCursor) || ('\t' == *reader.pCursor) || ('\n' == *reader.pCursor) || ('\r' == *reader.pCursor)))
    {
        ++reader.pCursor;
    }
    CVK_ASSERT(reader.pCursor == reader.pEnd);

    return reader.valueCount;
}
const cvkJsonValue* cvkGetJsonMember(const cvkJsonDocument* pDocument, const cvkJsonValue* pObject, const char* pKey)
{
    const size_t length = strlen(pKey);
    uint32_t     index;

    if ((NULL == pObject) || (CVK_JSON_OBJECT != pObject->kind))
    {
        return NULL;
    }
    for (index = pObject->firstChild; CVK_JSON_NONE != index; index = pDocument->pValues[index].nextSibling)
    {
        const cvkJsonValue* member = &pDocument->pValues[index];

        if ((member->keyLength == length) && (0 == memcmp(member->pKey, pKey, length)))
        {
            return member;
        }
    }

    return NULL;
}
const cvkJsonValue* cvkGetJsonElement(const cvkJsonDocument* pDocument, const cvkJsonValue* pArray, uint32_t index)
{
    uint32_t child;

    if ((NULL == pArray) || ((CVK_JSON_ARRAY != pArray->kind) && (CVK_JSON_OBJECT != pArray->kind)) || (index >= pArray->childCount))
    {
        return NULL;
    }
    for (child = pArray->firstChild; 0 != index; --index)
    {
        child = pDocument->pValues[child].nextSibling;
    }

    return &pDocument->pValues[child];
}
VkBool32 cvkJsonStringEquals(const cvkJsonValue* pValue, const char* pString)
{
    const size_t length = strlen(pString);

    return ((NULL != pValue) && (CVK_JSON_STRING == pValue->kind) && (pValue->textLength == length) && (0 == memcmp(pValue->pText, pString, length))) ? VK_TRUE : VK_FALSE;
}
VkBool32 cvkIsJsonNull(const cvkJsonValue* pValue)
{
    return ((NULL == pValue) || (CVK_JSON_NULL == pValue->kind) || cvkJsonStringEquals(pValue, "NULL")) ? VK_TRUE : VK_FALSE;
}
uint64_t cvkParseUint64Text(const char* pText)
{
    uint64_t value;
    uint32_t base;
    uint32_t digit;
    VkBool32 negative;

    value    = 0;
    base     = 10;
    negative = VK_FALSE;
    while (isspace((unsigned char)*pText))
    {
        ++pText;
    }
    if (('-' == *pText) || ('+' == *pText))
    {
        negative = ('-' == *pText) ? VK_TRUE : VK_FALSE;
        ++pText;
    }
    if ('0' == *pText)
    {
        base = 8;
        ++pText;
        if (('x' == *pText) || ('X' == *pText))
        {
            base = 16;
            ++pText;
        }
    }
    while ('\0' != *pText)
    {
        if (('0' <= *pText) && (*pText <= '9'))
        {
            digit = (uint32_t)(*pText - '0');
        }
        else if (('a' <= *pText) && (*pText <= 'f'))
        {
            digit = (uint32_t)(*pText - 'a') + 10;
        }
        else if (('A' <= *pText) && (*pText <= 'F'))
        {
            digit = (uint32_t)(*pText - 'A') + 10;
        }
        else
        {
            break;
        }
        if (digit >= base)
        {
            break;
        }
        if (value > (UINT64_MAX - digit) / base)
        {
            return UINT64_MAX;
        }
        value = value * base + digit;
        ++pText;
    }

    return negative ? (uint64_t)0 - value : value;
}
uint64_t cvkGetJsonUint64(const cvkJsonValue* pValue)
{
    char buffer[32];

    if ((NULL == pValue) || ((CVK_JSON_NUMBER != pValue->kind) && (CVK_JSON_STRING != pValue->kind)) || (pValue->textLength >= sizeof(buffer)))
    {
        return 0;
    }
    (void)memcpy(buffer, pValue->pText, pValue->textLength);

    buffer[pValue->textLength] = '\0';

    return cvkParseUint64Text(buffer);
}
int64_t cvkGetJsonInt64(const cvkJsonValue* pValue)
{
    char        buffer[32];
    const char* text;
    uint64_t    magnitude;
    VkBool32    negative;

    if ((NULL == pValue) || ((CVK_JSON_NUMBER != pValue->kind) && (CVK_JSON_STRING != pValue->kind)) || (pValue->textLength >= sizeof(buffer)))
    {
        return 0;
    }
    (void)memcpy(buffer, pValue->pText, pValue->textLength);

    buffer[pValue->textLength] = '\0';
    text                       = buffer;
    while (isspace((unsigned char)*text))
    {
        ++text;
    }
    negative = ('-' == *text) ? VK_TRUE : VK_FALSE;
    if (('-' == *text) || ('+' == *text))
    {
        ++text;
    }
    if ((*text < '0') || (*text > '9'))
    {
        return 0;
    }
    magnitude = cvkParseUint64Text(text);
    if (negative)
    {
        return magnitude > (uint64_t)INT64_MAX ? INT64_MIN : -(int64_t)magnitude;
    }

    return magnitude > (uint64_t)INT64_MAX ? INT64_MAX : (int64_t)magnitude;
}
double cvkGetJsonDouble(const cvkJsonValue* pValue)
{
    char buffer[64];

    if ((NULL == pValue) || ((CVK_JSON_NUMBER != pValue->kind) && (CVK_JSON_STRING != pValue->kind)) || (pValue->textLength >= sizeof(buffer)))
    {
        return 0.0;
    }
    (void)memcpy(buffer, pValue->pText, pValue->textLength);

    buffer[pValue->textLength] = '\0';

    return strtod(buffer, NULL);
}
VkBool32 cvkGetJsonBool32(const cvkJsonValue* pValue)
{
    if (NULL == pValue)
    {
        return VK_FALSE;
    }
    if (CVK_JSON_TRUE == pValue->kind || cvkJsonStringEquals(pValue, "VK_TRUE"))
    {
        return VK_TRUE;
    }
    if (CVK_JSON_NUMBER == pValue->kind)
    {
        return (0 != cvkGetJsonInt64(pValue)) ? VK_TRUE : VK_FALSE;
    }

    return VK_FALSE;
}
VkBool32 cvkLookupJsonName(const cvkJsonName* pTable, uint32_t tableCount, const char* pName, uint32_t nameLength, uint64_t* pValue)
{
    uint32_t index;

    for (index = 0; index < tableCount; ++index)
    {
        if ((strlen(pTable[index].pName) == nameLength) && (0 == memcmp(pTable[index].pName, pName, nameLength)))
        {
            (*pValue) = pTable[index].value;

            return VK_TRUE;
        }
    }

    return VK_FALSE;
}
uint64_t cvkParseJsonEnumerant(const cvkJsonValue* pValue, const cvkJsonName* pTable, uint32_t tableCount)
{
    uint64_t found;

    if ((NULL == pValue) || (CVK_JSON_NULL == pValue->kind))
    {
        return 0;
    }
    if (CVK_JSON_NUMBER == pValue->kind)
    {
        return (uint64_t)cvkGetJsonInt64(pValue);
    }
    CVK_ASSERT(CVK_JSON_STRING == pValue->kind);

    if (cvkLookupJsonName(pTable, tableCount, pValue->pText, pValue->textLength, &found))
    {
        return found;
    }

    return (uint64_t)cvkGetJsonInt64(pValue); /* a number written as a string ("0") */
}
uint64_t cvkParseJsonFlags(const cvkJsonValue* pValue, const cvkJsonName* pTable, uint32_t tableCount)
{
    uint64_t    flags = 0;
    const char* p;
    const char* end;

    if ((NULL == pValue) || (CVK_JSON_NULL == pValue->kind))
    {
        return 0;
    }
    if (CVK_JSON_NUMBER == pValue->kind)
    {
        return cvkGetJsonUint64(pValue);
    }
    CVK_ASSERT(CVK_JSON_STRING == pValue->kind);

    p   = pValue->pText;
    end = p + pValue->textLength;
    while (p < end)
    {
        const char* token;
        const char* token_end;
        uint64_t    bit;

        while ((p < end) && ((' ' == *p) || ('|' == *p)))
        {
            ++p;
        }
        token = p;
        while ((p < end) && (' ' != *p) && ('|' != *p))
        {
            ++p;
        }
        token_end = p;
        if (token_end == token)
        {
            break;
        }
        if ((1 == token_end - token) && ('0' == *token))
        {
            continue;
        }
        if (cvkLookupJsonName(pTable, tableCount, token, (uint32_t)(token_end - token), &bit))
        {
            flags |= bit;
        }
        else
        {
            char buffer[32];

            CVK_ASSERT((size_t)(token_end - token) < sizeof(buffer));

            (void)memcpy(buffer, token, (size_t)(token_end - token));

            buffer[token_end - token] = '\0';

            flags |= cvkParseUint64Text(buffer); /* a numeric token */
        }
    }

    return flags;
}
void* cvkAllocateArena(cvkArena* pArena, size_t size, size_t alignment)
{
    size_t offset;

    if (0 == size)
    {
        return NULL;
    }
    offset = (pArena->used + alignment - 1) & ~(alignment - 1);
    CVK_ASSERT(offset + size <= pArena->size);

    pArena->used = offset + size;

    return pArena->pBase + offset;
}
char* cvkCopyJsonString(cvkArena* pArena, const cvkJsonValue* pValue)
{
    char*    out;
    uint32_t i;
    uint32_t n = 0;

    if (cvkIsJsonNull(pValue) || (CVK_JSON_STRING != pValue->kind))
    {
        return NULL;
    }
    out = (char*)cvkAllocateArena(pArena, (size_t)pValue->textLength + 1, 1);
    for (i = 0; i < pValue->textLength; ++i)
    {
        char c = pValue->pText[i];

        if (('\\' == c) && (i + 1 < pValue->textLength))
        {
            c = pValue->pText[++i];
            switch (c)
            {
            case 'n':
                c = '\n';
                break;
            case 't':
                c = '\t';
                break;
            case 'r':
                c = '\r';
                break;
            case 'b':
                c = '\b';
                break;
            case 'f':
                c = '\f';
                break;
            case 'u':
                c = '?';
                i += 4;
                break;
            default:
                break;
            }
        }
        out[n++] = c;
    }
    out[n] = '\0';

    return out;
}
uint64_t cvkResolveJsonHandle(const cvkJsonContext* pContext, const char* pHandleType, const cvkJsonValue* pValue)
{
    uint64_t id;

    if (cvkIsJsonNull(pValue) || ((CVK_JSON_STRING == pValue->kind) && (0 == pValue->textLength)))
    {
        return 0;
    }
    id = cvkGetJsonUint64(pValue);

    return (NULL != pContext->resolveHandle) ? pContext->resolveHandle(pContext->pUser, pHandleType, id) : id;
}
uint32_t cvkParsePipelineJsonObjectList(const cvkJsonContext* pContext, const cvkJsonValue* pList, size_t elementSize, uint64_t** ppIds, void** ppElements)
{
    uint32_t count;
    uint32_t index;

    count = ((NULL != pList) && (CVK_JSON_ARRAY == pList->kind)) ? pList->childCount : 0;

    (*ppIds) = (uint64_t*)cvkAllocateArena(pContext->pArena, count * sizeof(uint64_t), sizeof(uint64_t));

    (*ppElements) = cvkAllocateArena(pContext->pArena, count * elementSize, 16);
    for (index = 0; index < count; ++index)
    {
        const cvkJsonValue* entry = cvkGetJsonElement(&pContext->document, pList, index);

        const cvkJsonValue* member = cvkGetJsonElement(&pContext->document, entry, 0); /* the one member: id -> structure */
        char                buffer[32];

        CVK_ASSERT((NULL != member) && (member->keyLength < sizeof(buffer)));

        (void)memcpy(buffer, member->pKey, member->keyLength);

        buffer[member->keyLength] = '\0';

        (*ppIds)[index] = cvkParseUint64Text(buffer);
    }

    return count;
}
void cvkParsePipelineJson(const cvkJsonContext* pContext, cvkPipelineJson* pPipeline)
{
    const cvkJsonValue* root = &pContext->document.pValues[0];
    const cvkJsonValue* state;
    const cvkJsonValue* value;
    const cvkJsonValue* list;
    void*               elements;
    uint32_t            index;

    (void)memset(pPipeline, 0, sizeof(*pPipeline));

    state = cvkGetJsonMember(&pContext->document, root, "GraphicsPipelineState");
    if (NULL != state)
    {
        pPipeline->bindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;

        value = cvkGetJsonMember(&pContext->document, state, "GraphicsPipeline");
        if (NULL != value)
        {
            cvkParseJsonGraphicsPipelineCreateInfo(pContext, value, &pPipeline->graphicsPipelineCreateInfo);
        }
    }
    else
    {
        state = cvkGetJsonMember(&pContext->document, root, "ComputePipelineState");
        CVK_ASSERT(NULL != state);

        pPipeline->bindPoint = VK_PIPELINE_BIND_POINT_COMPUTE;

        value = cvkGetJsonMember(&pContext->document, state, "ComputePipeline");
        if (NULL != value)
        {
            cvkParseJsonComputePipelineCreateInfo(pContext, value, &pPipeline->computePipelineCreateInfo);
        }
    }

    /* render pass: the sType decides the version */
    value = cvkGetJsonMember(&pContext->document, state, "Renderpass");
    if (!cvkIsJsonNull(value))
    {
        if (cvkJsonStringEquals(cvkGetJsonMember(&pContext->document, value, "sType"), "VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO_2"))
        {
            pPipeline->renderPassVersion = 2;

            cvkParseJsonRenderPassCreateInfo2(pContext, value, &pPipeline->renderPassCreateInfo2);
        }
        else
        {
            pPipeline->renderPassVersion = 1;

            cvkParseJsonRenderPassCreateInfo(pContext, value, &pPipeline->renderPassCreateInfo);
        }
    }

    /* objects by id */
    list = cvkGetJsonMember(&pContext->document, state, "DescriptorSetLayouts");

    pPipeline->descriptorSetLayoutCount = cvkParsePipelineJsonObjectList(pContext, list, sizeof(VkDescriptorSetLayoutCreateInfo), &pPipeline->pDescriptorSetLayoutIds, &elements);

    pPipeline->pDescriptorSetLayoutCreateInfos = (VkDescriptorSetLayoutCreateInfo*)elements;
    for (index = 0; index < pPipeline->descriptorSetLayoutCount; ++index)
    {
        cvkParseJsonDescriptorSetLayoutCreateInfo(pContext,
                                                  cvkGetJsonElement(&pContext->document, cvkGetJsonElement(&pContext->document, list, index), 0),
                                                  &pPipeline->pDescriptorSetLayoutCreateInfos[index]);
    }
    list = cvkGetJsonMember(&pContext->document, state, "Samplers");
    if (NULL == list)
    {
        list = cvkGetJsonMember(&pContext->document, state, "ImmutableSamplers");
    }
    pPipeline->samplerCount = cvkParsePipelineJsonObjectList(pContext, list, sizeof(VkSamplerCreateInfo), &pPipeline->pSamplerIds, &elements);

    pPipeline->pSamplerCreateInfos = (VkSamplerCreateInfo*)elements;
    for (index = 0; index < pPipeline->samplerCount; ++index)
    {
        cvkParseJsonSamplerCreateInfo(pContext, cvkGetJsonElement(&pContext->document, cvkGetJsonElement(&pContext->document, list, index), 0), &pPipeline->pSamplerCreateInfos[index]);
    }
    list = cvkGetJsonMember(&pContext->document, state, "YcbcrSamplers");

    pPipeline->samplerYcbcrConversionCount = cvkParsePipelineJsonObjectList(pContext, list, sizeof(VkSamplerYcbcrConversionCreateInfo), &pPipeline->pSamplerYcbcrConversionIds, &elements);

    pPipeline->pSamplerYcbcrConversionCreateInfos = (VkSamplerYcbcrConversionCreateInfo*)elements;
    for (index = 0; index < pPipeline->samplerYcbcrConversionCount; ++index)
    {
        cvkParseJsonSamplerYcbcrConversionCreateInfo(pContext,
                                                     cvkGetJsonElement(&pContext->document, cvkGetJsonElement(&pContext->document, list, index), 0),
                                                     &pPipeline->pSamplerYcbcrConversionCreateInfos[index]);
    }

    /* the pipeline layout */
    value = cvkGetJsonMember(&pContext->document, state, "PipelineLayout");
    if (!cvkIsJsonNull(value))
    {
        pPipeline->hasPipelineLayout = VK_TRUE;

        cvkParseJsonPipelineLayoutCreateInfo(pContext, value, &pPipeline->pipelineLayoutCreateInfo);
    }

    /* shaders: stage and file name */
    list = cvkGetJsonMember(&pContext->document, state, "ShaderFileNames");

    pPipeline->shaderCount = ((NULL != list) && (CVK_JSON_ARRAY == list->kind)) ? list->childCount : 0;

    pPipeline->pShaderStages = (VkShaderStageFlagBits*)cvkAllocateArena(pContext->pArena, pPipeline->shaderCount * sizeof(VkShaderStageFlagBits), sizeof(VkShaderStageFlagBits));

    pPipeline->ppShaderFileNames = (const char**)cvkAllocateArena(pContext->pArena, pPipeline->shaderCount * sizeof(const char*), sizeof(const char*));
    for (index = 0; index < pPipeline->shaderCount; ++index)
    {
        const cvkJsonValue* shader = cvkGetJsonElement(&pContext->document, list, index);

        pPipeline->pShaderStages[index] = cvkParseJsonShaderStageFlagBits(cvkGetJsonMember(&pContext->document, shader, "stage"));

        pPipeline->ppShaderFileNames[index] = cvkCopyJsonString(pContext->pArena, cvkGetJsonMember(&pContext->document, shader, "filename"));
    }

    /* document-level: extensions and the pipeline identifier */
    list = cvkGetJsonMember(&pContext->document, root, "EnabledExtensions");

    pPipeline->enabledExtensionCount = ((NULL != list) && (CVK_JSON_ARRAY == list->kind)) ? list->childCount : 0;

    pPipeline->ppEnabledExtensionNames = (const char**)cvkAllocateArena(pContext->pArena, pPipeline->enabledExtensionCount * sizeof(const char*), sizeof(const char*));
    for (index = 0; index < pPipeline->enabledExtensionCount; ++index)
    {
        pPipeline->ppEnabledExtensionNames[index] = cvkCopyJsonString(pContext->pArena, cvkGetJsonElement(&pContext->document, list, index));
    }
    list = cvkGetJsonMember(&pContext->document, root, "PipelineUUID");
    if ((NULL != list) && (CVK_JSON_ARRAY == list->kind) && (VK_UUID_SIZE == list->childCount))
    {
        pPipeline->hasPipelineUuid = VK_TRUE;
        for (index = 0; index < VK_UUID_SIZE; ++index)
        {
            pPipeline->pipelineUuid[index] = (uint8_t)cvkGetJsonUint64(cvkGetJsonElement(&pContext->document, list, index));
        }
    }
}
uint64_t cvkGetPipelineJsonHandle(uint32_t count, const uint64_t* pIds, const uint64_t* pHandles, uint64_t id)
{
    uint32_t index;

    for (index = 0; index < count; ++index)
    {
        if (pIds[index] == id)
        {
            return pHandles[index];
        }
    }

    return 0;
}
void cvkCreatePipelineJsonObjects(VkDevice                     device,
                                  VkPipelineCache              pipelineCache,
                                  const cvkPipelineJson*       pPipeline,
                                  const void*                  pPipelineNext,
                                  PFN_cvkResolveJsonHandle     resolveExternal,
                                  void*                        pUser,
                                  cvkArena*                    pArena,
                                  const VkAllocationCallbacks* pAllocator,
                                  cvkPipelineJsonObjects*      pObjects)
{
    uint64_t sampler_handles[CVK_MAX_PIPELINE_JSON_OBJECTS];
    uint64_t descriptor_set_layout_handles[CVK_MAX_PIPELINE_JSON_OBJECTS];
    uint32_t index;
    uint32_t inner;

    (void)memset(pObjects, 0, sizeof(*pObjects));
    CVK_ASSERT(CVK_MAX_PIPELINE_JSON_OBJECTS >= pPipeline->samplerYcbcrConversionCount);
    CVK_ASSERT(CVK_MAX_PIPELINE_JSON_OBJECTS >= pPipeline->samplerCount);
    CVK_ASSERT(CVK_MAX_PIPELINE_JSON_OBJECTS >= pPipeline->descriptorSetLayoutCount);

    /* Ycbcr conversions */
    pObjects->samplerYcbcrConversionCount = pPipeline->samplerYcbcrConversionCount;
    for (index = 0; index < pPipeline->samplerYcbcrConversionCount; ++index)
    {
        const VkSamplerYcbcrConversionCreateInfo* info = &pPipeline->pSamplerYcbcrConversionCreateInfos[index];

        pObjects->samplerYcbcrConversionIds[index] = pPipeline->pSamplerYcbcrConversionIds[index];

        cvkCreateSamplerYcbcrConversion(device,
                                        info->pNext,
                                        info->format,
                                        info->ycbcrModel,
                                        info->ycbcrRange,
                                        info->components,
                                        info->xChromaOffset,
                                        info->yChromaOffset,
                                        info->chromaFilter,
                                        info->forceExplicitReconstruction,
                                        pAllocator,
                                        &pObjects->samplerYcbcrConversions[index]);
    }

    /* samplers */
    pObjects->samplerCount = pPipeline->samplerCount;
    for (index = 0; index < pPipeline->samplerCount; ++index)
    {
        const VkSamplerCreateInfo* info = &pPipeline->pSamplerCreateInfos[index];

        pObjects->samplerIds[index] = pPipeline->pSamplerIds[index];

        cvkCreateSampler(device,
                         info->pNext,
                         info->flags,
                         info->magFilter,
                         info->minFilter,
                         info->mipmapMode,
                         info->addressModeU,
                         info->addressModeV,
                         info->addressModeW,
                         info->mipLodBias,
                         info->anisotropyEnable,
                         info->maxAnisotropy,
                         info->compareEnable,
                         info->compareOp,
                         info->minLod,
                         info->maxLod,
                         info->borderColor,
                         info->unnormalizedCoordinates,
                         pAllocator,
                         &pObjects->samplers[index]);

        sampler_handles[index] = (uint64_t)(uintptr_t)pObjects->samplers[index];
    }

    /* descriptor set layouts, immutable sampler ids resolved */
    pObjects->descriptorSetLayoutCount = pPipeline->descriptorSetLayoutCount;
    for (index = 0; index < pPipeline->descriptorSetLayoutCount; ++index)
    {
        const VkDescriptorSetLayoutCreateInfo* info = &pPipeline->pDescriptorSetLayoutCreateInfos[index];

        VkDescriptorSetLayoutBinding* bindings = (VkDescriptorSetLayoutBinding*)cvkAllocateArena(pArena, info->bindingCount * sizeof(VkDescriptorSetLayoutBinding), 8);

        for (inner = 0; inner < info->bindingCount; ++inner)
        {
            bindings[inner] = info->pBindings[inner];
            if (NULL != bindings[inner].pImmutableSamplers)
            {
                VkSampler* samplers = (VkSampler*)cvkAllocateArena(pArena, bindings[inner].descriptorCount * sizeof(VkSampler), 8);
                uint32_t   s;

                for (s = 0; s < bindings[inner].descriptorCount; ++s)
                {
                    samplers[s] = (VkSampler)(uintptr_t)
                        cvkGetPipelineJsonHandle(pObjects->samplerCount, pObjects->samplerIds, sampler_handles, (uint64_t)(uintptr_t)info->pBindings[inner].pImmutableSamplers[s]);
                }
                bindings[inner].pImmutableSamplers = samplers;
            }
        }
        pObjects->descriptorSetLayoutIds[index] = pPipeline->pDescriptorSetLayoutIds[index];

        cvkCreateDescriptorSetLayout(device, info->pNext, info->flags, info->bindingCount, bindings, pAllocator, &pObjects->descriptorSetLayouts[index]);

        descriptor_set_layout_handles[index] = (uint64_t)(uintptr_t)pObjects->descriptorSetLayouts[index];
    }

    /* pipeline layout, set layout ids resolved */
    if (pPipeline->hasPipelineLayout)
    {
        const VkPipelineLayoutCreateInfo* info = &pPipeline->pipelineLayoutCreateInfo;

        VkDescriptorSetLayout* layouts = (VkDescriptorSetLayout*)cvkAllocateArena(pArena, info->setLayoutCount * sizeof(VkDescriptorSetLayout), 8);

        for (inner = 0; inner < info->setLayoutCount; ++inner)
        {
            layouts[inner] = (VkDescriptorSetLayout)(uintptr_t)
                cvkGetPipelineJsonHandle(pObjects->descriptorSetLayoutCount, pObjects->descriptorSetLayoutIds, descriptor_set_layout_handles, (uint64_t)(uintptr_t)info->pSetLayouts[inner]);
        }
        cvkCreatePipelineLayout(device, info->pNext, info->flags, info->setLayoutCount, layouts, info->pushConstantRangeCount, info->pPushConstantRanges, pAllocator, &pObjects->pipelineLayout);
    }

    /* render pass */
    if (1 == pPipeline->renderPassVersion)
    {
        const VkRenderPassCreateInfo* info = &pPipeline->renderPassCreateInfo;

        cvkCreateRenderPass(device,
                            info->pNext,
                            info->flags,
                            info->attachmentCount,
                            info->pAttachments,
                            info->subpassCount,
                            info->pSubpasses,
                            info->dependencyCount,
                            info->pDependencies,
                            pAllocator,
                            &pObjects->renderPass);
    }
    else if (2 == pPipeline->renderPassVersion)
    {
        const VkRenderPassCreateInfo2* info = &pPipeline->renderPassCreateInfo2;

        cvkCreateRenderPass2(device,
                             info->pNext,
                             info->flags,
                             info->attachmentCount,
                             info->pAttachments,
                             info->subpassCount,
                             info->pSubpasses,
                             info->dependencyCount,
                             info->pDependencies,
                             info->correlatedViewMaskCount,
                             info->pCorrelatedViewMasks,
                             pAllocator,
                             &pObjects->renderPass);
    }

    /* the pipeline */
    if (VK_PIPELINE_BIND_POINT_GRAPHICS == pPipeline->bindPoint)
    {
        const VkGraphicsPipelineCreateInfo* info = &pPipeline->graphicsPipelineCreateInfo;

        VkPipelineShaderStageCreateInfo* stages = (VkPipelineShaderStageCreateInfo*)cvkAllocateArena(pArena, info->stageCount * sizeof(VkPipelineShaderStageCreateInfo), 8);

        for (inner = 0; inner < info->stageCount; ++inner)
        {
            stages[inner] = info->pStages[inner];

            stages[inner].module = (NULL != resolveExternal) ? (VkShaderModule)(uintptr_t)resolveExternal(pUser, "VkShaderModule", (uint64_t)(uintptr_t)info->pStages[inner].module) : VK_NULL_HANDLE;
        }
        cvkCreateGraphicsPipeline(device,
                                  pipelineCache,
                                  (NULL != pPipelineNext) ? pPipelineNext : info->pNext,
                                  info->flags,
                                  info->stageCount,
                                  stages,
                                  info->pVertexInputState,
                                  info->pInputAssemblyState,
                                  info->pTessellationState,
                                  info->pViewportState,
                                  info->pRasterizationState,
                                  info->pMultisampleState,
                                  info->pDepthStencilState,
                                  info->pColorBlendState,
                                  info->pDynamicState,
                                  pObjects->pipelineLayout,
                                  pObjects->renderPass,
                                  info->subpass,
                                  VK_NULL_HANDLE,
                                  -1,
                                  pAllocator,
                                  &pObjects->pipeline);
    }
    else
    {
        const VkComputePipelineCreateInfo* info  = &pPipeline->computePipelineCreateInfo;
        VkPipelineShaderStageCreateInfo    stage = info->stage;

        stage.module = (NULL != resolveExternal) ? (VkShaderModule)(uintptr_t)resolveExternal(pUser, "VkShaderModule", (uint64_t)(uintptr_t)info->stage.module) : VK_NULL_HANDLE;

        cvkCreateComputePipeline(device,
                                 pipelineCache,
                                 (NULL != pPipelineNext) ? pPipelineNext : info->pNext,
                                 info->flags,
                                 stage,
                                 pObjects->pipelineLayout,
                                 VK_NULL_HANDLE,
                                 -1,
                                 pAllocator,
                                 &pObjects->pipeline);
    }
}
void cvkCreatePipelineFromJson(VkDevice                     device,
                               VkPipelineCache              pipelineCache,
                               const char*                  pJsonText,
                               size_t                       jsonLength,
                               cvkJsonValue*                pJsonValues,
                               uint32_t                     jsonValueCapacity,
                               cvkArena*                    pArena,
                               PFN_cvkResolveJsonHandle     resolveExternal,
                               void*                        pUser,
                               const VkAllocationCallbacks* pAllocator,
                               cvkPipelineJson*             pPipeline,
                               cvkPipelineJsonObjects*      pObjects)
{
    cvkJsonContext context;

    context.document.pValues = pJsonValues;

    context.document.valueCount = cvkParseJsonDocument(pJsonText, jsonLength, pJsonValues, jsonValueCapacity);

    context.pArena        = pArena;
    context.resolveHandle = NULL;
    context.pUser         = NULL;

    cvkParsePipelineJson(&context, pPipeline);
    cvkCreatePipelineJsonObjects(device, pipelineCache, pPipeline, NULL, resolveExternal, pUser, pArena, pAllocator, pObjects);
}
